/** The link that opens a screen: the app's address with `open` naming it. */
export const SCREEN_LINK = { path: "/app/plan", key: "open", scheme: "wingtipmaps", schemeHost: "plan" } as const;

/** The screens a link opens on the web, by the id the link names. */
export const SCREENS = {
  fpl: { title: "FPL" },
  airport: { title: "Airport" },
  airplane: { title: "Airplane" },
  setup: { title: "Setup" },
  brief: { title: "Brief" },
  navlog: { title: "Nav Log" },
  profile: { title: "Profile" },
  flights: { title: "Saved Flights" },
  favorites: { title: "Favorites" },
  nearest: { title: "Nearest" },
  emergency: { title: "Emergency Assistant" },
  checklists: { title: "Checklists" },
  airplanes: { title: "Your Airplanes" },
  logbook: { title: "Logbook" },
  coach: { title: "Coach" },
  minimums: { title: "Personal Minimums" },
  guide: { title: "Guide" },
  shared: { title: "Shared Flight" },
  about: { title: "About" },
  search: { title: "Search" },
} as const;

export type ScreenId = keyof typeof SCREENS;

/** The plan's own keys a link carries beside `open` (a shared flight's among them). */
export const LINK_KEYS = ["dep", "dest", "stops", "place", "flight", "airplane", "tfr", "navaid", "altitude_ft", "depart", "type", "rules", "tail", "share"] as const;

export type LinkKey = (typeof LINK_KEYS)[number];

/** The screen a link's value names, or null for none the web has. */
export function screenOf(value: string | null | undefined): ScreenId | null {
  return value && Object.hasOwn(SCREENS, value) ? (value as ScreenId) : null;
}

/** The link to a screen, at `origin` (the site's, for a link to share). */
export function screenLink(id: ScreenId, origin = ""): string {
  return `${origin}${SCREEN_LINK.path}?${SCREEN_LINK.key}=${id}`;
}
